156	  auto vector_data_buffer = core_interface::VectorDataBuffer();
157	
158	  if (0 != index->fetch(doc_id, &vector_data_buffer)) {
159	    return tl::make_unexpected(
160	        Status::InternalError("Failed to fetch vector from index"));
161	  }
162	  return ProximaEngineHelper::move_from_engine_vector_buffer(
163	             std::move(vector_data_buffer), is_sparse_)
164	      .value();
