167	Result<IndexResults::Ptr> VectorColumnIndexer::Search(
168	    const vector_column_params::VectorData &vector_data,
169	    const vector_column_params::QueryParams &query_params) {
170	  if (index == nullptr) {
171	    return tl::make_unexpected(Status::InvalidArgument("Index not opened"));
172	  }
173	
174	  auto engine_vector_data =
175	      ProximaEngineHelper::convert_to_engine_vector(vector_data, is_sparse_);
176	  core_interface::SearchResult search_result;
177	  auto engine_query_param_result =
178	      ProximaEngineHelper::convert_to_engine_query_param(field_schema_,
179	                                                         query_params);
180	  if (!engine_query_param_result.has_value()) {
181	    return tl::make_unexpected(engine_query_param_result.error());
182	  }
183	  auto &engine_query_param = engine_query_param_result.value();
184	  if (query_params.bf_pks.size() > 1) {
185	    LOG_ERROR("bf_pks size > 1 is not supported");
186	    return tl::make_unexpected(
187	        Status::InvalidArgument("bf_pks size > 1 is not supported"));
188	  } else if (query_params.bf_pks.size() == 1) {
189	    auto &bf_pks = query_params.bf_pks[0];
190	    engine_query_param->bf_pks =
191	        std::make_shared<std::vector<uint64_t>>(std::move(bf_pks));
192	  } else {
193	    engine_query_param->bf_pks = nullptr;
194	  }
195	  if (0 != index->search(engine_vector_data.value(),
196	                         std::move(engine_query_param), &search_result)) {
197	    return tl::make_unexpected(
198	        Status::InternalError("Failed to search vector"));
199	  }
200	
201	  // Return grouped results when group_by is active
202	  if (!search_result.group_doc_list_.empty()) {
203	    auto result = std::make_shared<GroupVectorIndexResults>(
204	        std::move(search_result.group_doc_list_),
205	        std::move(search_result.group_reverted_vector_list_),
206	        std::move(search_result.group_reverted_sparse_values_list_));
207	    return result;
208	  }
209	
210	  auto result = std::make_shared<VectorIndexResults>(
211	      is_sparse_, std::move(search_result.doc_list_),
212	      std::move(search_result.reverted_vector_list_),
213	      std::move(search_result.reverted_sparse_values_list_));
214	  return result;
215	}
